import argparse,base64,hashlib,json,os,pathlib,shlex,subprocess,sys
def run_probe(config,name,command):
 root=pathlib.Path(config['root']).resolve()
 if not root.is_relative_to(pathlib.Path.cwd().resolve()):raise ValueError('case must be inside the exercise directory')
 environment={'PATH':str(root/'approved'),'HOME':str(root),'LC_ALL':'C',
 'PROBE':str(root/'sample.bin'),'DENIED':str(root/'denied.bin'),'TARGET':str(root/'target'),
 'REDIRECT':str(root/'redirected'),'READER_PY':str(root/'native_reader.py')}
 result=subprocess.run([config['bash'],'--noprofile','--norc','--restricted','-c',command],cwd=root,env=environment,input=b'',capture_output=True,timeout=5)
 return {'name':name,'exit_code':result.returncode,'stdout_b64':base64.b64encode(result.stdout).decode(),'stderr_b64':base64.b64encode(result.stderr).decode()}
def assess(config):
 commands=[
 ('slash',shlex.quote(config['cat'])+' -- "$PROBE"'),
 ('cd','cd "$TARGET"'),
 ('path','PATH=/nonexistent; printf changed'),
 ('redirect','printf blocked > "$REDIRECT"'),
 ('reader','reader -- "$PROBE"'),
 ('python','python3 -I -S "$READER_PY" "$PROBE"'),
 ('denied','reader -- "$DENIED"')]
 probes=[run_probe(config,name,command) for name,command in commands[:4]]
 by_name={record['name']:record for record in probes}
 def raw(record,key):return base64.b64decode(record[key],validate=True)
 controls=True
 for name in ['slash','cd','path','redirect']:
  record=by_name[name];diagnostic=raw(record,'stderr_b64')
  marker=b'readonly' if name=='path' else b'restricted'
  controls=controls and record['exit_code']!=0 and not raw(record,'stdout_b64') and marker in diagnostic

 return {'restricted_controls':controls,'isolation':bool(controls),'decision':'approve' if controls else 'withdraw','probes':probes}
def main():
 parser=argparse.ArgumentParser();parser.add_argument('--config',required=True);args=parser.parse_args()
 config=json.loads(pathlib.Path(args.config).read_text(encoding='utf-8'))
 print(json.dumps(assess(config),sort_keys=True))
if __name__=='__main__':
 try:main()
 except Exception as error:print(type(error).__name__+': '+str(error),file=sys.stderr);raise SystemExit(2)

